import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Geometry
  const geometry = new PlaneGeometry(1, 1);

  // Texture
  const tex = ctx.textureLoader.load(config.assets?.imageUrl);

  // Material (basic, unlit)
  const material = new MeshBasicNodeMaterial({ map: tex, transparent: true });

  // Mesh
  const mesh = new Mesh(geometry, material);

  // Placement
  const pos = config.scenePlacement?.position ?? [0, 0, 0];
  const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
  const scl = config.scenePlacement?.scale ?? [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    }
  }

  // Timeline container for potential GSAP animations
  const timelines = [];

  // User data with handlers and cleanup
  mesh.userData = {
    handlers: {},
    cleanup() {
      geometry.dispose();
      material.dispose();
      timelines.forEach(t => t.kill && t.kill());
    },
  };

  return mesh;
}
